(function(){'use strict';const $=s=>document.querySelector(s),M=Manager,owner=(new URLSearchParams(location.search).get('owner')||'').toLowerCase(),actor=KashierData.userId();let snapshot=null,selected=null,request=0,receiptRequest=0,loading=false;
const active=()=>actor&&KashierData.loggedIn()&&KashierData.userId()===actor,node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);return e;},status=t=>$('#manager-status').textContent=t;
function clear(){snapshot=selected=null;$('#manager-title').textContent='ڕاپۆرتی دوکان';$('#manager-paper').hidden=$('#manager-receipt').hidden=true;for(const id of ['rows','summary','receipt'])$('#manager-'+id).replaceChildren();$('#manager-meta').textContent='';$('#manager-print').disabled=$('#manager-csv').disabled=$('#manager-receipt-print').disabled=true;}
function invalidate(){request++;receiptRequest++;loading=false;clear();$('#manager-load').disabled=false;}
function actorName(r){return r.actor_name||(r.actor_id===owner?'خاوەن':'ئەنجامدەر تۆمار نەکراوە');}
function render(s){document.body.setAttribute('data-manager-print','report');$('#manager-title').textContent=s.store_name+' — فرۆشتن و گەڕاندنەوە';$('#manager-meta').textContent=s.from+' → '+s.to+' · کاتی بەغدا · '+s.generated_at;for(const [label,value] of [['فرۆشتنی دوای داشکاندن',s.sales_total],['بەهای گەڕاندنەوە',s.returns_total],['فرۆشتنی دوای گەڕاندنەوە',s.net_total],['کاشی فرۆشتن و گەڕاندنەوە',s.cash_net],['گۆڕانی قەرزی فرۆشتن و گەڕاندنەوە',s.debt_net],['داشکاندنی فرۆشتنەکانی ماوە',s.discounts]]){const box=node('div');box.append(node('dt',label+' / دینار'),node('dd',M.money(value)));$('#manager-summary').append(box);}for(const r of s.rows){const row=node('tr'),source=node('td'),b=node('button',M.prefix[r.kind]+r.reference_no);b.addEventListener('click',()=>show(r.sale_id));source.append(b,node('br'),'K-'+r.receipt_no);row.append(source,node('td',r.day),node('td',M.kinds[r.kind]+' · '+(r.mode==='cash'?'کاش':'قەرز')),node('td',r.customer_name||'—'),node('td',actorName(r)),node('td',M.money(r.amount)),node('td',M.money(r.cash)),node('td',M.money(r.debt)));$('#manager-rows').append(row);}$('#manager-empty').hidden=s.count!==0;$('#manager-paper').hidden=false;$('#manager-print').disabled=$('#manager-csv').disabled=false;}
async function load(print=false){if(loading)return;invalidate();if(!active()){location.replace('auth.html?next='+encodeURIComponent('manager.html?owner='+owner));return;}if(!M.uuid(owner)){status('ناسنامەی دوکان نادروستە.');return;}const mine=++request,from=$('#manager-from').value,to=$('#manager-to').value;loading=true;$('#manager-load').disabled=true;status('خوێندنەوەی ڕاپۆرتی دوکان…');try{M.range(from,to);const s=await KashierData.getManagerSalesReport(owner,from,to);if(mine!==request)return;if(!active())throw Error('هەژمارەکە گۆڕاوە.');M.report(s,from,to,owner,actor);snapshot=s;render(s);status('ڕاپۆرت ئامادەیە.');if(print){document.body.setAttribute('data-manager-print','report');window.print();}}catch(e){if(mine===request){clear();status((globalThis.KashierLocale?.message(e.message)??e.message));}}finally{if(mine===request){loading=false;$('#manager-load').disabled=false;}}}
function renderReceipt(s){document.body.setAttribute('data-manager-print','receipt');selected=s;const v=s.sale,z=s.returns,paper=$('#manager-receipt');paper.replaceChildren(node('h2',s.store_name+' · K-'+v.receipt_no),node('p',new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(v.created_at))),node('p','کڕیار: '+(v.customer_name||'—')),node('p','شێوازی فرۆشتن: '+(v.payment_mode==='cash'?'کاش':'قەرز')),node('p','کاشێر: '+actorName(v)));const table=node('table'),head=node('tr');for(const label of ['کاڵا','بڕ / یەکە','نرخ / دینار','کۆ / دینار'])head.append(node('th',label));table.append(head);for(const x of v.lines){const r=node('tr');r.append(node('td',x.name),node('td',M.quantity(String(x.quantity_units))),node('td',M.money(x.unit_price)),node('td',M.money(x.line_total)));table.append(r);}paper.append(table);for(const [label,value] of [['کۆی کاڵاکان',v.subtotal],['داشکاندن',v.discount],['کۆی کۆتایی پسوولە',v.total],['وەرگیراوی کاتی فرۆشتن',v.received],['پارەی گەڕاندنەوەی کاتی فرۆشتن',v.change_due],['قەرزی کاتی فرۆشتن',v.debt_amount]])paper.append(node('p',label+': '+M.money(value)+' دینار'));paper.append(node('p',(z.full?'بە تەواوی گەڕێندراوەتەوە':'گەڕاندنەوەکان: '+z.count)+' · بەها: '+M.money(z.total)+' · کاش: '+M.money(z.cash_refund)+' · قەرزی هەڵوەشاوە: '+M.money(z.debt_reversed)),node('p','ئەمانە بڕەکانی پسوولە و گەڕاندنەوەکانن؛ قەرزی ئێستای کڕیار لەم پەڕەیە حساب ناکرێت.'),node('p',v.note),node('small',v.id));paper.hidden=false;$('#manager-receipt-print').disabled=false;}
async function show(id,print=false){if(!active()){invalidate();return;}const mine=++receiptRequest,life=request;selected=null;$('#manager-receipt').hidden=true;$('#manager-receipt-print').disabled=true;try{const s=await KashierData.getManagerReceipt(owner,id);if(mine!==receiptRequest||life!==request)return;if(!active())throw Error('هەژمارەکە گۆڕاوە.');M.receipt(s,owner,actor,id);renderReceipt(s);if(print){document.body.setAttribute('data-manager-print','receipt');window.print();}}catch(e){if(mine===receiptRequest&&life===request){selected=null;$('#manager-receipt').replaceChildren();$('#manager-receipt').hidden=true;if(['staff_access_denied','staff_manager_required'].includes(e.saleCode))invalidate();status((globalThis.KashierLocale?.message(e.message)??e.message));}}}
function usable(){if(!active()){invalidate();return false;}return Boolean(snapshot);}
$('#manager-form').addEventListener('submit',e=>{e.preventDefault();load();});for(const id of ['from','to'])$('#manager-'+id).addEventListener('input',invalidate);$('#manager-print').addEventListener('click',()=>{if(usable())load(true);});$('#manager-receipt-print').addEventListener('click',()=>{if(selected&&active())show(selected.sale.id,true);});$('#manager-csv').addEventListener('click',()=>{if(!usable())return;const url=URL.createObjectURL(new Blob([M.csv(snapshot)],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download='kashier-store-sales-'+snapshot.from+'-'+snapshot.to+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});window.addEventListener('beforeprint',()=>{if(!active())invalidate();});window.addEventListener('pagehide',invalidate);window.addEventListener('pageshow',e=>{if(e.persisted)invalidate();});const today=M.day(new Date());$('#manager-from').value=today.slice(0,8)+'01';$('#manager-to').value=today;load();})();
